pub fn parse_size(s: &str) -> Option<u64> {
    let b = s.as_bytes();
    let is_ws = |c: u8| matches!(c, b' ' | b'\t' | b'\n' | b'\r' | b'\x0b' | b'\x0c');

    let mut i = 0usize;
    while i < b.len() && is_ws(b[i]) {
        i += 1;
    }

    let mut value: u64 = 0;
    let mut any_digit = false;
    while i < b.len() && b[i].is_ascii_digit() {
        value = value.checked_mul(10)?.checked_add((b[i] - b'0') as u64)?;
        any_digit = true;
        i += 1;
    }
    if !any_digit {
        return None;
    }

    while i < b.len() && is_ws(b[i]) {
        i += 1;
    }

    let mut end = b.len();
    while end > i && is_ws(b[end - 1]) {
        end -= 1;
    }

    let suffix = &b[i..end];
    let multiplier: u64 = if suffix.is_empty()
        || (suffix.len() == 1 && suffix[0].eq_ignore_ascii_case(b'B'))
    {
        1
    } else if suffix.len() == 3
        && suffix[0].eq_ignore_ascii_case(b'K')
        && suffix[1].eq_ignore_ascii_case(b'i')
        && suffix[2].eq_ignore_ascii_case(b'B')
    {
        1024
    } else if suffix.len() == 3
        && suffix[0].eq_ignore_ascii_case(b'M')
        && suffix[1].eq_ignore_ascii_case(b'i')
        && suffix[2].eq_ignore_ascii_case(b'B')
    {
        1024 * 1024
    } else if suffix.len() == 3
        && suffix[0].eq_ignore_ascii_case(b'G')
        && suffix[1].eq_ignore_ascii_case(b'i')
        && suffix[2].eq_ignore_ascii_case(b'B')
    {
        1024 * 1024 * 1024
    } else if suffix.len() == 3
        && suffix[0].eq_ignore_ascii_case(b'T')
        && suffix[1].eq_ignore_ascii_case(b'i')
        && suffix[2].eq_ignore_ascii_case(b'B')
    {
        1024 * 1024 * 1024 * 1024
    } else if suffix.len() == 2
        && suffix[0].eq_ignore_ascii_case(b'K')
        && suffix[1].eq_ignore_ascii_case(b'B')
    {
        1000
    } else if suffix.len() == 2
        && suffix[0].eq_ignore_ascii_case(b'M')
        && suffix[1].eq_ignore_ascii_case(b'B')
    {
        1000 * 1000
    } else if suffix.len() == 2
        && suffix[0].eq_ignore_ascii_case(b'G')
        && suffix[1].eq_ignore_ascii_case(b'B')
    {
        1000 * 1000 * 1000
    } else if suffix.len() == 2
        && suffix[0].eq_ignore_ascii_case(b'T')
        && suffix[1].eq_ignore_ascii_case(b'B')
    {
        1000 * 1000 * 1000 * 1000
    } else {
        return None;
    };

    value.checked_mul(multiplier)
}
