pub fn parse_range_list(s: &str) -> Option<Vec<u32>> {
    if s.trim_matches(|c: char| {
        c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\u{B}' || c == '\u{C}'
    })
    .is_empty()
    {
        return Some(Vec::new());
    }

    let parse_number = |text: &str| -> Option<u32> {
        let text = text.trim_matches(|c: char| {
            c == ' '
                || c == '\t'
                || c == '\n'
                || c == '\r'
                || c == '\u{B}'
                || c == '\u{C}'
        });

        if text.is_empty() {
            return None;
        }

        let mut value: u32 = 0;
        for b in text.bytes() {
            if !b.is_ascii_digit() {
                return None;
            }

            let digit = u32::from(b - b'0');
            value = value.checked_mul(10)?.checked_add(digit)?;
        }

        Some(value)
    };

    let mut out = Vec::new();

    for item in s.split(',') {
        let item = item.trim_matches(|c: char| {
            c == ' '
                || c == '\t'
                || c == '\n'
                || c == '\r'
                || c == '\u{B}'
                || c == '\u{C}'
        });

        if item.is_empty() {
            return None;
        }

        let parts: Vec<&str> = item.splitn(3, '-').collect();

        match parts.len() {
            1 => {
                let n = parse_number(parts[0])?;
                out.push(n);
            }
            2 => {
                let start = parse_number(parts[0])?;
                let end = parse_number(parts[1])?;

                if start > end {
                    return None;
                }

                for n in start..=end {
                    out.push(n);
                }
            }
            _ => return None,
        }
    }

    Some(out)
}
