pub fn parse_range_list(s: &str) -> Option<Vec<u32>> {
    if s.trim_matches(|c: char| c.is_ascii_whitespace()).is_empty() {
        return Some(Vec::new());
    }

    let parse_u32 = |text: &str| -> Option<u32> {
        let text = text.trim_matches(|c: char| c.is_ascii_whitespace());
        if text.is_empty() {
            return None;
        }

        let mut value: u32 = 0;
        for ch in text.chars() {
            if !ch.is_ascii_digit() {
                return None;
            }
            let digit = ch as u32 - '0' as u32;
            value = value.checked_mul(10)?.checked_add(digit)?;
        }
        Some(value)
    };

    let mut result = Vec::new();
    for item in s.split(',') {
        let item = item.trim_matches(|c: char| c.is_ascii_whitespace());
        if item.is_empty() {
            return None;
        }

        if let Some(pos) = item.find('-') {
            let start = parse_u32(&item[..pos])?;
            let end = parse_u32(&item[pos + 1..])?;
            if start > end {
                return None;
            }

            let mut n = start;
            loop {
                result.push(n);
                if n == end {
                    break;
                }
                n += 1;
            }
        } else {
            result.push(parse_u32(item)?);
        }
    }

    Some(result)
}
